-- Phase 1: staff temporary PIN lifecycle.
-- PIN values are never stored here; pin_hash stores a PBKDF2 digest generated by the Edge Function.

alter table public.app_user
  add column if not exists must_change_pin boolean not null default false;

create or replace function public.normalize_ug_phone_value(p_phone text)
returns text
language sql
immutable
set search_path = pg_catalog
as $$
  select case
    when length(digits) = 10 and left(digits, 2) = '07' then '256' || substr(digits, 2)
    when length(digits) = 12 and left(digits, 4) = '2567' then digits
    else digits
  end
  from (select regexp_replace(coalesce(p_phone, ''), '[^0-9]', '', 'g') as digits) normalized
$$;

create unique index if not exists uq_app_user_active_phone
  on public.app_user (public.normalize_ug_phone_value(phone))
  where status = 'active';

create or replace function public.provision_staff_account_v1(
  p_actor_id uuid,
  p_user_id uuid,
  p_full_name text,
  p_role text,
  p_phone text,
  p_username text,
  p_start_date date,
  p_pin_hash text
)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_actor app_user%rowtype;
begin
  select * into v_actor from public.app_user where id = p_actor_id and status = 'active';
  if v_actor.id is null or v_actor.status <> 'active' or v_actor.role <> 'hr' then
    raise exception 'Only active HR may provision staff accounts.' using errcode = '42501';
  end if;
  if p_role not in ('staff', 'receptionist', 'manager') then
    raise exception 'Unsupported account role.' using errcode = '22023';
  end if;
  if p_full_name is null or length(trim(p_full_name)) < 2 then
    raise exception 'Enter the staff member full name.' using errcode = '22023';
  end if;
  if p_username is null or p_username !~ '^[a-z0-9._]{3,20}$' then
    raise exception 'Username must be 3 to 20 lowercase letters, digits, dots, or underscores.' using errcode = '22023';
  end if;
  if p_phone !~ '^\+2567[0-9]{8}$' then
    raise exception 'Enter a valid Uganda mobile number.' using errcode = '22023';
  end if;
  if p_pin_hash is null or p_pin_hash = '' then
    raise exception 'Temporary PIN digest is required.' using errcode = '22023';
  end if;

  insert into public.app_user (
    id, organization_id, location_id, full_name, display_name, phone,
    role, status, start_date, pin_hash, must_change_pin
  ) values (
    p_user_id, v_actor.organization_id, v_actor.location_id, trim(p_full_name),
    split_part(trim(p_full_name), ' ', 1), p_phone, p_role::app_role, 'active',
    coalesce(p_start_date, current_date), p_pin_hash, true
  );

  insert into public.app_setting as current_setting (location_id, key, value)
  values (
    v_actor.location_id,
    'hr_user_checklists',
    jsonb_build_object(p_user_id::text, jsonb_build_object('onboarding', jsonb_build_array('account_created', 'pin_given')))
  )
  on conflict (location_id, key) do update
    set value = jsonb_set(
      coalesce(current_setting.value, '{}'::jsonb),
      array[p_user_id::text],
      jsonb_build_object('onboarding', jsonb_build_array('account_created', 'pin_given')),
      true
    );

  insert into public.audit_log (
    organization_id, location_id, actor_id, actor_role, action,
    entity_type, entity_id, category, reason, after
  ) values (
    v_actor.organization_id, v_actor.location_id, p_actor_id, 'hr',
    'CREATE_ACCOUNT', 'app_user', p_user_id::text, 'people',
    'HR created an account', jsonb_build_object('role', p_role)
  );
end;
$$;

create or replace function public.set_temporary_pin_v1(
  p_actor_id uuid,
  p_user_id uuid,
  p_pin_hash text
)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_actor app_user%rowtype;
  v_target app_user%rowtype;
begin
  select * into v_actor from public.app_user where id = p_actor_id and status = 'active';
  select * into v_target from public.app_user where id = p_user_id and status = 'active';
  if v_target.id is null then
    raise exception 'Active target account not found.' using errcode = 'P0002';
  end if;
  if v_actor.id is null then
    raise exception 'Active actor account not found.' using errcode = '42501';
  end if;
  if v_actor.role = 'hr' then
    null;
  elsif v_actor.role = 'manager' and v_target.role in ('staff', 'receptionist') then
    null;
  else
    raise exception 'This role cannot reset the target PIN.' using errcode = '42501';
  end if;
  if v_actor.organization_id is distinct from v_target.organization_id
     or v_actor.location_id is distinct from v_target.location_id then
    raise exception 'The target account is outside the actor location.' using errcode = '42501';
  end if;
  if p_pin_hash is null or p_pin_hash = '' then
    raise exception 'Temporary PIN digest is required.' using errcode = '22023';
  end if;

  update public.app_user
    set pin_hash = p_pin_hash, must_change_pin = true, updated_at = now()
    where id = p_user_id;

  -- Revoke active refresh sessions for the target. Existing access tokens are
  -- still bounded by their short JWT lifetime; the route middleware requires
  -- the user to authenticate again before accessing the workspace.
  delete from auth.sessions where user_id = p_user_id;

  insert into public.audit_log (
    organization_id, location_id, actor_id, actor_role, action,
    entity_type, entity_id, category, reason, after
  ) values (
    v_actor.organization_id, v_actor.location_id, p_actor_id, v_actor.role::text,
    'RESET_PIN', 'app_user', p_user_id::text, 'access',
    'Temporary PIN reset', jsonb_build_object('role', v_target.role::text)
  );
end;
$$;

create or replace function public.complete_temporary_pin_change_v1(
  p_user_id uuid
)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_user app_user%rowtype;
begin
  select * into v_user from public.app_user where id = p_user_id and status = 'active';
  if not found then
    raise exception 'Active account not found.' using errcode = 'P0002';
  end if;
  update public.app_user
    set must_change_pin = false, pin_hash = null, updated_at = now()
    where id = p_user_id;
  insert into public.audit_log (
    organization_id, location_id, actor_id, actor_role, action,
    entity_type, entity_id, category, reason, after
  ) values (
    v_user.organization_id, v_user.location_id, p_user_id, v_user.role::text,
    'PIN_CHANGED', 'app_user', p_user_id::text, 'access',
    'Temporary PIN changed', jsonb_build_object('role', v_user.role::text)
  );
end;
$$;

revoke all on function public.provision_staff_account_v1(uuid, uuid, text, text, text, text, date, text) from public, anon, authenticated;
revoke all on function public.set_temporary_pin_v1(uuid, uuid, text) from public, anon, authenticated;
revoke all on function public.complete_temporary_pin_change_v1(uuid) from public, anon, authenticated;
grant execute on function public.provision_staff_account_v1(uuid, uuid, text, text, text, text, date, text) to service_role;
grant execute on function public.set_temporary_pin_v1(uuid, uuid, text) to service_role;
grant execute on function public.complete_temporary_pin_change_v1(uuid) to service_role;
